import{c as r,Q as o,j as d,m as n}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-嵌入式","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-嵌入式"},"headers":[],"relativePath":"综合知识/系统基础/嵌入式.md","filePath":"综合知识/系统基础/嵌入式.md","lastUpdated":null}'),s={name:"综合知识/系统基础/嵌入式.md"};function a(e,t,l,g,h,i){return o(),d("div",null,[...t[0]||(t[0]=[n('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 嵌入式系统组成与特征</li><li>[x] 冯诺依曼结构与哈佛结构</li><li>[x] 微处理器分类（MCU/MPU/DSP/SOC）</li><li>[x] 多核处理器（SMP/AMP、全局队列/局部队列调度）</li><li>[x] 嵌入式软件分类与 BSP（BootLoader + 设备驱动程序）</li><li>[x] 嵌入式操作系统（EOS）特点</li><li>[x] 实时操作系统（RTOS）— 硬实时/软实时</li><li>[x] 嵌入式数据库系统（EDBMS）</li><li>[x] 交叉开发环境（交叉编译/交叉调试）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><blockquote><p>历年考情：本章节偶尔考到，一般占 3~5 分。第二版教材描述简略，实际考试约 50% 超纲。</p></blockquote><hr><h3 id="一、嵌入式系统组成与特征" tabindex="-1">一、嵌入式系统组成与特征 <a class="header-anchor" href="#一、嵌入式系统组成与特征" aria-label="Permalink to &quot;一、嵌入式系统组成与特征&quot;">​</a></h3><p><strong>组成</strong>：嵌入式处理器 + 相关支撑硬件 + 嵌入式操作系统 + 支撑软件 + 应用软件</p><p><strong>八大特征：</strong></p><table tabindex="0"><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>专用性强</strong></td><td>面向特定应用，把板卡任务集成到芯片内部，利于小型化</td></tr><tr><td><strong>技术融合</strong></td><td>计算机、通信、半导体、电子技术与行业应用结合</td></tr><tr><td><strong>软硬一体软件为主</strong></td><td>软件是主体，硬件软件均量体裁衣去除冗余</td></tr><tr><td><strong>比通用计算机资源少</strong></td><td>只完成少数任务，管理资源少、成本低、结构简单</td></tr><tr><td><strong>程序代码固化在非易失存储器</strong></td><td>软件固化在 ROM/Flash 中，非磁盘存储</td></tr><tr><td><strong>需专门开发工具和环境</strong></td><td>本身不具备开发能力，需交叉开发环境</td></tr><tr><td><strong>体积小、价格低、实时性强</strong></td><td>系统配置要求低</td></tr><tr><td><strong>安全性和可靠性要求高</strong></td><td>常运行在恶劣环境下</td></tr></tbody></table><p><strong>系统分层（5 层）</strong>：硬件层 → 抽象层 → 操作系统层 → 中间件层 → 应用层</p><p><strong>系统分类：</strong></p><ul><li>按用途：嵌入式实时系统 / 嵌入式非实时系统</li><li>按安全性：安全攸关系统 / 非安全攸关系统</li></ul><hr><h3 id="二、嵌入式微处理器" tabindex="-1">二、嵌入式微处理器 <a class="header-anchor" href="#二、嵌入式微处理器" aria-label="Permalink to &quot;二、嵌入式微处理器&quot;">​</a></h3><h4 id="冯诺依曼结构-vs-哈佛结构" tabindex="-1">冯诺依曼结构 vs 哈佛结构 <a class="header-anchor" href="#冯诺依曼结构-vs-哈佛结构" aria-label="Permalink to &quot;冯诺依曼结构 vs 哈佛结构&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对比维度</th><th>冯诺依曼结构</th><th>哈佛结构</th></tr></thead><tbody><tr><td><strong>存储方式</strong></td><td>程序和数据共用一个存储空间</td><td>程序和数据存储在<strong>不同</strong>的存储空间</td></tr><tr><td><strong>总线</strong></td><td>单一的地址及数据总线</td><td>两套独立的地址总线和数据总线</td></tr><tr><td><strong>并行性</strong></td><td>指令和数据串行访问</td><td><strong>一个机器周期内同时获取指令字和操作数</strong></td></tr><tr><td><strong>效率</strong></td><td>高速运算时传输出瓶颈</td><td>数据吞吐率提高 1 倍，执行速度更快</td></tr><tr><td><strong>典型应用</strong></td><td>传统通用计算机</td><td>DSP、嵌入式处理器</td></tr></tbody></table><h4 id="微处理器分类" tabindex="-1">微处理器分类 <a class="header-anchor" href="#微处理器分类" aria-label="Permalink to &quot;微处理器分类&quot;">​</a></h4><p><strong>按字长宽度：</strong></p><ul><li>16 位及以下 → <strong>嵌入式微控制器</strong>（MCU）</li><li>32 位及以上 → <strong>嵌入式微处理器</strong>（MPU）</li></ul><p><strong>按系统集成度：</strong></p><ul><li>一般用途型微处理器（仅 CPU）</li><li>单芯片微控制器（CPU+ROM+RAM+I/O 集成）</li></ul><p><strong>按用途分类：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>典型应用</th></tr></thead><tbody><tr><td><strong>MCU</strong>（微控制器）</td><td>典型代表：<strong>单片机</strong>。片上外设资源丰富，体积小、功耗低成本低、可靠性高。嵌入式系统工业<strong>主流</strong></td><td>控制类应用</td></tr><tr><td><strong>MPU</strong>（微处理器）</td><td>由通用 CPU 演变，<strong>32 位以上</strong>，保留嵌入式相关功能硬件，去除冗余。体积小、重量轻、成本低、可靠性高</td><td>ARM、MIPS、PowerPC</td></tr><tr><td><strong>DSP</strong>（数字信号处理器）</td><td>专门用于信号处理，<strong>哈佛结构 + 流水线处理</strong>，处理速度比最快 CPU 还快 10-50 倍</td><td>数字滤波、FFT、谱分析</td></tr><tr><td><strong>SOC</strong>（片上系统）</td><td>追求最大包容的集成器件，实现<strong>软硬件无缝结合</strong>，片内嵌入操作系统代码模块</td><td>专用集成电路</td></tr></tbody></table><hr><h3 id="三、多核处理器" tabindex="-1">三、多核处理器 <a class="header-anchor" href="#三、多核处理器" aria-label="Permalink to &quot;三、多核处理器&quot;">​</a></h3><blockquote><p>多核指多个微处理器内核，将两个或更多的独立处理器封装在一起，<strong>集成在一个电路中</strong>。多核与多 CPU 相比，<strong>很好的降低了计算机系统的功耗和体积</strong>。</p></blockquote><p><strong>两种协调方式：</strong></p><table tabindex="0"><thead><tr><th>方式</th><th>特点</th></tr></thead><tbody><tr><td><strong>SMP</strong>（对称多处理）</td><td>2 颗完全一样的处理器封装在一个芯片内，达到双倍性能，节省运算资源</td></tr><tr><td><strong>AMP</strong>（非对称处理）</td><td>2 个处理内核彼此不同，各自处理特定功能，软件协调分担不同计算任务</td></tr></tbody></table><blockquote><p>⚠️ 多核处理器结构选择<strong>必须考虑硬件组成差异</strong>。</p></blockquote><p><strong>多核 CPU 调度：</strong></p><table tabindex="0"><thead><tr><th>调度方式</th><th>机制</th><th>优点</th></tr></thead><tbody><tr><td><strong>全局队列调度</strong></td><td>操作系统维护一个全局任务等待队列，CPU 空闲时从中选取任务执行</td><td>CPU 核心利用率高</td></tr><tr><td><strong>局部队列调度</strong></td><td>每个 CPU 内核维护独立的局部任务等待队列</td><td>无需在多个 CPU 之间切换</td></tr></tbody></table><hr><h3 id="四、嵌入式软件与-bsp" tabindex="-1">四、嵌入式软件与 BSP <a class="header-anchor" href="#四、嵌入式软件与-bsp" aria-label="Permalink to &quot;四、嵌入式软件与 BSP&quot;">​</a></h3><p><strong>软件分类：</strong></p><table tabindex="0"><thead><tr><th>类别</th><th>说明</th></tr></thead><tbody><tr><td><strong>系统软件</strong></td><td>控制和管理嵌入式系统资源，如设备驱动程序、嵌入式操作系统、嵌入式中间件</td></tr><tr><td><strong>应用软件</strong></td><td>上层软件，定义设备主要功能和用途，负责与用户交互</td></tr><tr><td><strong>支撑软件</strong></td><td>辅助软件开发的工具，如系统分析设计工具、在线仿真工具、交叉编译器</td></tr></tbody></table><p><strong>嵌入式软件特点</strong>：规模较小、开发难度大、实时性和可靠性要求高、要求固化存储。</p><h4 id="板级支持包-bsp" tabindex="-1">板级支持包（BSP） <a class="header-anchor" href="#板级支持包-bsp" aria-label="Permalink to &quot;板级支持包（BSP）&quot;">​</a></h4><blockquote><p>BSP 是<strong>介于主板硬件和操作系统中驱动层程序之间的一层</strong>，属于操作系统一部分。为上层的驱动程序提供访问硬件设备寄存器的函数包。</p></blockquote><p><strong>功能：</strong></p><ol><li>单板硬件初始化（主要是 CPU 初始化）</li><li>为操作系统提供设备驱动程序和系统中断服务程序</li><li>定制操作系统的功能，提供实时多任务的运行环境</li><li>初始化操作系统，为正常运行做好准备</li></ol><p><strong>两大特点</strong>：① 硬件相关性 ② 操作系统相关性</p><p><strong>BSP 两大组成部分：</strong></p><table tabindex="0"><thead><tr><th>组成</th><th>说明</th></tr></thead><tbody><tr><td><strong>BootLoader</strong>（引导加载程序）</td><td>加电后运行的第一段软件代码</td></tr><tr><td><strong>设备驱动程序</strong></td><td>对硬件进行初始化和管理</td></tr></tbody></table><h4 id="bootloader-三阶段" tabindex="-1">BootLoader 三阶段 <a class="header-anchor" href="#bootloader-三阶段" aria-label="Permalink to &quot;BootLoader 三阶段&quot;">​</a></h4><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>性质</th></tr></thead><tbody><tr><td><strong>片级初始化</strong></td><td>微处理器初始化：设置核心寄存器、控制寄存器、工作模式及局部总线模式</td><td>纯硬件初始化</td></tr><tr><td><strong>板级初始化</strong></td><td>微处理器以外的硬件初始化：LED、定时器、中断控制器、串口、内存控制器、建立内存空间地址映射</td><td>软硬件结合的初始化</td></tr><tr><td><strong>加载内核</strong>（系统级初始化）</td><td>将操作系统和应用程序映像从 Flash 复制到内存，跳转到系统内核第一条指令</td><td>—</td></tr></tbody></table><h4 id="设备驱动程序" tabindex="-1">设备驱动程序 <a class="header-anchor" href="#设备驱动程序" aria-label="Permalink to &quot;设备驱动程序&quot;">​</a></h4><blockquote><p>设备驱动程序是<strong>一组库函数</strong>，用来对硬件进行初始化和管理，向上层软件提供良好访问接口。无论是否有操作系统，驱动程序都<strong>必不可少</strong>。</p></blockquote><p><strong>基本功能</strong>：硬件启动、硬件关闭、硬件停用、硬件启用、读操作、写操作。</p><hr><h3 id="五、嵌入式操作系统-eos" tabindex="-1">五、嵌入式操作系统（EOS） <a class="header-anchor" href="#五、嵌入式操作系统-eos" aria-label="Permalink to &quot;五、嵌入式操作系统（EOS）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特点</th><th>说明</th></tr></thead><tbody><tr><td><strong>微型化</strong></td><td>运行平台资源少（内存小、无外存），必须小巧、占用尽量少资源</td></tr><tr><td><strong>代码质量高</strong></td><td>存储空间宝贵，代码要尽量精简</td></tr><tr><td><strong>专业化</strong></td><td>硬件平台多样、处理器更新快，要有好的适应性和移植性，支持多种开发平台</td></tr><tr><td><strong>实时性强</strong></td><td>广泛应用于过程控制、数据采集、通信等要求实时响应的场合</td></tr><tr><td><strong>可裁减和可配置</strong></td><td>能根据应用特点和具体要求灵活配置和合理裁减</td></tr></tbody></table><blockquote><p>⚠️ 嵌入式操作系统<strong>支持多任务</strong>，RTOS <strong>可以针对硬件变化进行结构与功能上的配置及裁剪</strong>。</p></blockquote><hr><h3 id="六、实时操作系统-rtos" tabindex="-1">六、实时操作系统（RTOS） <a class="header-anchor" href="#六、实时操作系统-rtos" aria-label="Permalink to &quot;六、实时操作系统（RTOS）&quot;">​</a></h3><blockquote><p>嵌入式实时系统要求系统在投入运行前即具有<strong>确定性和可预测性</strong>。提供<strong>及时响应和高可靠性</strong>是 RTOS 的主要特点。RTOS 的首要任务是<strong>调度一切可利用的资源来完成实时控制任务</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>要求</th></tr></thead><tbody><tr><td><strong>硬实时</strong></td><td>必须在规定时间内完成操作，操作系统设计时保证</td></tr><tr><td><strong>软实时</strong></td><td>按照任务优先级，尽可能快地完成操作即可</td></tr></tbody></table><p><strong>RTOS 三大特征：</strong></p><table tabindex="0"><thead><tr><th>特征</th><th>说明</th></tr></thead><tbody><tr><td><strong>高精度计时系统</strong></td><td>精确确定实时操作或执行任务的时间点，依赖于硬件时钟精度和操作系统高精度计时功能</td></tr><tr><td><strong>多级中断机制</strong></td><td>处理多种外部信息或事件，建立多级中断嵌套处理机制，确保紧迫程度高的实时事件及时响应</td></tr><tr><td><strong>实时调度机制</strong></td><td>在调度策略和算法上保证优先调度实时任务，建立更多&quot;安全切换&quot;时间点保证及时调度</td></tr></tbody></table><hr><h3 id="七、嵌入式数据库系统-edbms" tabindex="-1">七、嵌入式数据库系统（EDBMS） <a class="header-anchor" href="#七、嵌入式数据库系统-edbms" aria-label="Permalink to &quot;七、嵌入式数据库系统（EDBMS）&quot;">​</a></h3><p><strong>使用环境特点：</strong></p><ul><li>设备随时移动性</li><li>网络频繁断接</li><li>网络条件多样化</li><li>通信能力不对称（下行 &gt;&gt; 上行）</li></ul><p><strong>系统组成</strong>：主数据库、同步服务器、嵌入式数据库、连接网络</p><blockquote><p>关键问题：数据的<strong>一致性（复制性）</strong>、高效的事务处理、数据的安全性。</p></blockquote><hr><h3 id="八、交叉开发环境" tabindex="-1">八、交叉开发环境 <a class="header-anchor" href="#八、交叉开发环境" aria-label="Permalink to &quot;八、交叉开发环境&quot;">​</a></h3><blockquote><p>嵌入式系统的开发需要借助<strong>宿主机（通用计算机）<strong>来编译出</strong>目标机</strong>的可执行代码。宿主机与目标机之间需要建立<strong>物理连接</strong>（以太网、USB、串口等）。</p></blockquote><p><strong>交叉编译：</strong> 在宿主机上采用<strong>交叉编译器</strong>生成目标机的可执行代码。不同体系结构有不同的指令系统，需要相应编译器。</p><p><strong>交叉调试：</strong> 调试器运行在宿主机上，被调试进程运行在目标机上，通过串口/网络进行通信。</p><p><strong>开发工具链：</strong></p><ul><li><strong>编辑器</strong>：VS、eclipse、keil、vim 等</li><li><strong>编译器 gcc</strong>：GNU/C/C++，支持多种宿主机/目标机组合</li><li><strong>调试器 gdb</strong>：GNU 开源强大程序调试工具</li></ul><blockquote><p>⚠️ 在宿主机上<strong>必须</strong>采用交叉编译器来生成目标机的可执行代码。调试器与被调试程序<strong>可以</strong>安装在不同机器上。</p></blockquote>',72)])])}const u=r(s,[["render",a]]);export{p as __pageData,u as default};
